ST7735::ST7735(int csPin, int dcPin, int rstPin, int mosiPin, int sclkPin, int blPin)
    : Display(DISPLAY_WIDTH, DISPLAY_HEIGHT), 
      _csPin(csPin), _dcPin(dcPin), _rstPin(rstPin),
      _mosiPin(mosiPin), _sclkPin(sclkPin), _blPin(blPin) {}

esp_err_t ST7735::init() {
    if (_initialized) return ESP_OK;
    
    // Configure DC pin
    gpio_config_t gpioConf = {};
    gpioConf.pin_bit_mask = (1ULL << _dcPin);
    gpioConf.mode = GPIO_MODE_OUTPUT;
    gpioConf.pull_up_en = GPIO_PULLUP_DISABLE;
    gpioConf.pull_down_en = GPIO_PULLDOWN_DISABLE;
    gpioConf.intr_type = GPIO_INTR_DISABLE;
    gpio_config(&gpioConf);
    
    // Configure RST pin if used
    if (_rstPin >= 0) {
        gpioConf.pin_bit_mask = (1ULL << _rstPin);
        gpio_config(&gpioConf);
    }
    
    // Configure backlight pin if used
    if (_blPin >= 0) {
        gpioConf.pin_bit_mask = (1ULL << _blPin);
        gpio_config(&gpioConf);
        gpio_set_level((gpio_num_t)_blPin, 1);  // Turn backlight ON
        OSAL_LOGI("Backlight ON (GPIO %d)", _blPin);
    }
    
    // Initialize SPI bus
    spi_bus_config_t busConf = {};
    busConf.mosi_io_num = _mosiPin;
    busConf.miso_io_num = -1;
    busConf.sclk_io_num = _sclkPin;
    busConf.quadwp_io_num = -1;
    busConf.quadhd_io_num = -1;
    busConf.max_transfer_sz = DISPLAY_WIDTH * DISPLAY_HEIGHT * 2;
    
    esp_err_t ret = spi_bus_initialize(SPI2_HOST, &busConf, SPI_DMA_CH_AUTO);
    if (ret != ESP_OK && ret != ESP_ERR_INVALID_STATE) {
        OSAL_LOGE("SPI bus init failed: %s", esp_err_to_name(ret));
        return ret;
    }
    
    // Add SPI device
    spi_device_interface_config_t devConf = {};
    devConf.mode = 0;
    devConf.clock_speed_hz = 20000000;  // 40MHz default, configurable
    devConf.spics_io_num = _csPin;
    devConf.queue_size = 7;
    
    ret = spi_bus_add_device(SPI2_HOST, &devConf, &_spiHandle);
    if (ret != ESP_OK) {
        OSAL_LOGE("SPI device add failed: %s", esp_err_to_name(ret));
        return ret;
    }
    
    // Hardware reset
    if (_rstPin >= 0) {
        gpio_set_level((gpio_num_t)_rstPin, 0);
        vTaskDelay(pdMS_TO_TICKS(50));
        gpio_set_level((gpio_num_t)_rstPin, 1);
        vTaskDelay(pdMS_TO_TICKS(50));
    }
    
    // ST7735 initialization sequence
    sendCommand(0x01);  // Software reset
    vTaskDelay(pdMS_TO_TICKS(120));
    
    sendCommand(0x11);  // Sleep out
    vTaskDelay(pdMS_TO_TICKS(120));
    
    // Memory access control (MADCTL) - configure rotation and color order
    sendCommand(0x36);
    sendData(0x68);  // MY=1, MV=1, BGR=1 - landscape 160x80 (correct for ST7735S 160x80 panels)
    
    // Interface pixel format - 16-bit RGB565
    sendCommand(0x3A);
    sendData(0x05);
    
    // Normal display mode
    sendCommand(0x13);
    
    // Display inversion ON (needed for some panels like ST7735S 160x80)
    sendCommand(0x21);
    
    // Clear display
    clear(Color::BLACK);
    
    // Display ON
    sendCommand(0x29);
    vTaskDelay(pdMS_TO_TICKS(50));
    
    _initialized = true;
    OSAL_LOGI("Initialized %dx%d (offsets: col=%d, row=%d)", 
             DISPLAY_WIDTH, DISPLAY_HEIGHT, COL_OFFSET, ROW_OFFSET);
    return ESP_OK;
}

esp_err_t ST7735::deinit() {
    if (!_initialized) return ESP_OK;
    
    sendCommand(0x28);  // Display OFF
    sendCommand(0x10);  // Sleep IN
    
    if (_blPin >= 0) {
        gpio_set_level((gpio_num_t)_blPin, 0);  // Turn backlight OFF
    }
    
    if (_spiHandle) {
        spi_bus_remove_device(_spiHandle);
        _spiHandle = nullptr;
    }
    
    _initialized = false;
    return ESP_OK;
}

void ST7735::sendCommand(uint8_t cmd) {
    gpio_set_level((gpio_num_t)_dcPin, 0);
    spi_transaction_t trans = {};
    trans.length = 8;
    trans.tx_buffer = &cmd;
    spi_device_transmit(_spiHandle, &trans);
}

void ST7735::sendData(uint8_t data) {
    gpio_set_level((gpio_num_t)_dcPin, 1);
    spi_transaction_t trans = {};
    trans.length = 8;
    trans.tx_buffer = &data;
    spi_device_transmit(_spiHandle, &trans);
}

void ST7735::setWindow(int16_t x0, int16_t y0, int16_t x1, int16_t y1) {
    // Apply offsets for this display variant
    x0 += _colOffset;
    x1 += _colOffset;
    y0 += _rowOffset;
    y1 += _rowOffset;
    
    sendCommand(0x2A);  // Column address set
    sendData(x0 >> 8);
    sendData(x0 & 0xFF);
    sendData(x1 >> 8);
    sendData(x1 & 0xFF);
    
    sendCommand(0x2B);  // Row address set
    sendData(y0 >> 8);
    sendData(y0 & 0xFF);
    sendData(y1 >> 8);
    sendData(y1 & 0xFF);
    
    sendCommand(0x2C);  // Memory write
}

void ST7735::clear(uint16_t color) {
    fillRect(0, 0, _width, _height, color);
}

void ST7735::drawPixel(int16_t x, int16_t y, uint16_t color) {
    if (x < 0 || x >= _width || y < 0 || y >= _height) return;
    
    setWindow(x, y, x, y);
    uint8_t buf[2] = {(uint8_t)(color >> 8), (uint8_t)(color & 0xFF)};
    gpio_set_level((gpio_num_t)_dcPin, 1);
    spi_transaction_t trans = {};
    trans.length = 16;
    trans.tx_buffer = buf;
    spi_device_transmit(_spiHandle, &trans);
}

void ST7735::fillRect(int16_t x, int16_t y, int16_t w, int16_t h, uint16_t color) {
    if (!_initialized || w <= 0 || h <= 0) return;
    
    // Clamp to display bounds
    if (x < 0) { w += x; x = 0; }
    if (y < 0) { h += y; y = 0; }
    if (x + w > _width) w = _width - x;
    if (y + h > _height) h = _height - y;
    if (w <= 0 || h <= 0) return;
    
    setWindow(x, y, x + w - 1, y + h - 1);
    gpio_set_level((gpio_num_t)_dcPin, 1);
    
    // Use buffered DMA transfer for speed
    static uint8_t buf[512];  // 256 pixels worth
    uint8_t hi = color >> 8;
    uint8_t lo = color & 0xFF;
    
    for (int i = 0; i < 256; i++) {
        buf[i * 2] = hi;
        buf[i * 2 + 1] = lo;
    }
    
    int total = w * h;
    int sent = 0;
    
    while (sent < total) {
        int chunk = (total - sent);
        if (chunk > 256) chunk = 256;
        
        spi_transaction_t trans = {};
        trans.length = chunk * 16;
        trans.tx_buffer = buf;
        spi_device_transmit(_spiHandle, &trans);
        sent += chunk;
        
        // Yield periodically to prevent watchdog timeout on large fills
        if ((sent % 1024) == 0) { taskYIELD(); }
    }
}

void ST7735::setCursor(int16_t x, int16_t y) {
    _cursorX = x;
    _cursorY = y;
}

void ST7735::setTextColor(uint16_t fg, uint16_t bg) {
    _textColor = fg;
    _bgColor = bg;
}

void ST7735::setBacklight(uint8_t level) {
    if (_blPin >= 0) {
        gpio_set_level((gpio_num_t)_blPin, level > 0 ? 1 : 0);
    }
}

void ST7735::setRotation(uint8_t rotation) {
    _rotation = rotation & 3;
    
    uint8_t madctl = 0x08;  // BGR color order base
    
    switch (_rotation) {
        case 0:
            _width = DISPLAY_WIDTH;
            _height = DISPLAY_HEIGHT;
            _colOffset = COL_OFFSET;
            _rowOffset = ROW_OFFSET;
            break;
        case 1:
            madctl |= 0x60;  // MX + MV
            _width = DISPLAY_HEIGHT;
            _height = DISPLAY_WIDTH;
            _colOffset = ROW_OFFSET;
            _rowOffset = COL_OFFSET;
            break;
        case 2:
            madctl |= 0xC0;  // MY + MX
            _width = DISPLAY_WIDTH;
            _height = DISPLAY_HEIGHT;
            _colOffset = COL_OFFSET;
            _rowOffset = ROW_OFFSET;
            break;
        case 3:
            madctl |= 0xA0;  // MY + MV
            _width = DISPLAY_HEIGHT;
            _height = DISPLAY_WIDTH;
            _colOffset = ROW_OFFSET;
            _rowOffset = COL_OFFSET;
            break;
    }
    
    sendCommand(0x36);
    sendData(madctl);
}

/**
 * @brief Draw a character with BOTH foreground AND background in one transaction
 *        This eliminates flicker by not requiring a separate fillRect before text
 */
void ST7735::drawChar(int16_t x, int16_t y, char c, uint16_t color, uint16_t bg, uint8_t size) {
    (void)size;
    
    const uint8_t* glyph = nullptr;
    if ((uint8_t)c == 0xB0) {
        glyph = glyph_degree;
    } else if ((uint8_t)c == 0x01) {
        glyph = glyph_wifi;
    } else {
        if (c < 32 || c > 127) c = ' ';
        int idx = c - 32;
        if (idx < 0 || idx >= (int)(sizeof(font5x7) / sizeof(font5x7[0]))) {
            idx = 0;
        }
        glyph = font5x7[idx];
    }
    
    const int charW = 6;
    const int charH = 8;
    
    setWindow(x, y, x + charW - 1, y + charH - 1);
    gpio_set_level((gpio_num_t)_dcPin, 1);
    
    uint8_t buf[96];
    int bufIdx = 0;
    
    uint8_t fgHi = color >> 8;
    uint8_t fgLo = color & 0xFF;
    uint8_t bgHi = bg >> 8;
    uint8_t bgLo = bg & 0xFF;
    
    for (int row = 0; row < charH; row++) {
        for (int col = 0; col < charW; col++) {
            bool isFg = false;
            if (col < 5 && row < 7) {
                uint8_t line = glyph[col];
                isFg = (line & (1 << row)) != 0;
            }
            if (isFg) {
                buf[bufIdx++] = fgHi;
                buf[bufIdx++] = fgLo;
            } else {
                buf[bufIdx++] = bgHi;
                buf[bufIdx++] = bgLo;
            }
        }
    }
    
    spi_transaction_t trans = {};
    trans.length = bufIdx * 8;
    trans.tx_buffer = buf;
    spi_device_transmit(_spiHandle, &trans);
}

void ST7735::print(const char* str) {
    while (*str) {
        uint8_t c = (uint8_t)*str++;
        if (c == '\n') {
            _cursorX = 0;
            _cursorY += 9;
        } else if (c == 0xC2 && (uint8_t)*str == 0xB0) {
            str++;
            drawChar(_cursorX, _cursorY, (char)0xB0, _textColor, _bgColor, _textSize);
            _cursorX += 6;
        } else {
            drawChar(_cursorX, _cursorY, (char)c, _textColor, _bgColor, _textSize);
            _cursorX += 6;
        }
        
        // Wrap at display edge
        if (_cursorX >= _width - 6) {
            _cursorX = 0;
            _cursorY += 9;
        }
    }
}

